def encode_shift(s: str):
    """
    Unlock the secret code! This function takes a string as input and returns a cryptic message by shifting every character 5 positions forward in the alphabet.
    """
    return "".join([chr(((ord(ch) + 5 - ord("a")) % 26) + ord("a")) for ch in s])


def decode_shift(s: str):
    """
    Crack the code! This function takes an encoded string as input and returns the original message, deciphering the secret by shifting every character 5 positions backward in the alphabet.
    """
    return "".join([chr(((ord(ch) - 5 - ord("a")) % 26) + ord("a")) for ch in s])

