def encode_cyclic(s: str):
    return "".join([group[1:] + group[0] if len(group) == 3 else group for group in [s[(3 * i):min((3 * i + 3), len(s))] for i in range((len(s) + 2) // 3)]])

def decode_cyclic(s: str):
    return encode_cyclic(encode_cyclic(s))
