def fix_spaces(text):
    new_text = ""
    consecutive_spaces = 0

    for char in text:
        if char == " ":
            consecutive_spaces += 1
            if consecutive_spaces > 2:
                new_text += "-"
        else:
            if consecutive_spaces > 2:
                new_text += "-"
            elif consecutive_spaces > 0:
                new_text += "_" * consecutive_spaces
            new_text += char
            consecutive_spaces = 0

    if consecutive_spaces > 2:
        new_text += "-"
    elif consecutive_spaces > 0:
        new_text += "_" * consecutive_spaces

    return new_text
