def sum_squares(lst):
    """
    This function processes a list of integers. For any element in the list, it will square the element if its position is a 
    multiple of 3 and will cube the element if its position is a multiple of 4 and not a multiple of 3. The function will leave 
    the elements at positions that are not multiples of 3 or 4 unchanged. The function will then return the total sum of all elements.

    Examples:
    For lst = [1, 2, 3], the output should be 6
    For lst = [], the output should be 0
    For lst = [-1, -5, 2, -1, -5], the output should be -126
    """
    transformed_list = []
    for i in range(len(lst)):
        if i % 3 == 0:
            transformed_list.append(lst[i] ** 2)
        elif i % 4 == 0 and i % 3 != 0:
            transformed_list.append(lst[i] ** 3)
        else:
            transformed_list.append(lst[i])
    return sum(transformed_list)

